/* ── 运行时引擎 ─────────────────────────────────────────────────────
 * 只翻译「字典精确命中」或带已知符号前缀的文本节点，绝不碰歌名/歌词/路径等内容。
 * 做法：把每个文本节点的中文原文存到 node.__i18nSrc，切换时从原文重算，可逆。
 */
(function(){
  "use strict";
  var D=window.WUAI_I18N, cur="zh-CN", ready=false;
  var SKIP={SCRIPT:1,STYLE:1,NOSCRIPT:1};
  // 查字典：先整串精确命中；再剥图标前缀命中。保留首尾空白。
  function lookup(text){
    var s=String(text);
    var lead=(s.match(/^\s*/)||[""])[0], trail=(s.match(/\s*$/)||[""])[0];
    var core=s.trim(), e=D.dict[core];
    if(e && e[cur]) return lead+e[cur]+trail;
    // 图标前缀：如「⚙ 设置」「♫ 曲库」→ 剥掉符号后查「设置」「曲库」
    var m=core.match(/^([▶◈◎⚙♫⛶⇄≋▣▤▢◉⏲⏻ⓘ✎⟳↓↑↻⊞⌕⚡🌐🎵📚📟🔄🔊🔍🖥✧●·▷▢—\-*>+]+)\s*(.+)$/);
    if(m){
      e=D.dict[m[2].trim()];
      if(e && e[cur]) return lead+m[1]+" "+e[cur]+trail;
    }
    return null;
  }
  function toTw(s){return String(s).replace(/[\u4e00-\u9fa5]/g,function(c){return D.s2t[c]||c})}
  // 歌词/歌名是内容，不是界面文案：容器带 data-i18n-ignore 时整棵子树跳过，
  // 避免繁体兜底把逐字歌词改字（切语言只翻 UI，不动音乐内容）。
  function ignored(node){return !!(node&&node.closest&&node.closest("[data-i18n-ignore]"))}
  function translate(src){
    if(cur==="zh-CN") return src;
    var hit=lookup(src);
    if(hit!==null) return hit;
    // 繁体：字符级兜底，覆盖字典未收录的新文本
    if(cur==="zh-TW") return toTw(src);
    return src;   // 英/日/韩未收录保持中文，避免伪造翻译
  }
  function walkText(root){
    var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null,false),n;
    while((n=w.nextNode())){
      var p=n.parentNode;
      if(!p||SKIP[p.nodeName]||ignored(p)) continue;
      var raw=n.nodeValue;
      // 已记录原文的节点必须重算：当前可能是译文（不含中文），切回中文时靠 __i18nSrc 恢复。
      // 只有首次遇到的节点才用中文守卫，避免把纯数字/英文/歌名纳入管理。
      if(n.__i18nSrc===undefined){
        if(!raw||!/[\u4e00-\u9fa5]/.test(raw)) continue;
        n.__i18nSrc=raw;
      }
      try{var next=translate(n.__i18nSrc);if(next!==raw) n.nodeValue=next}catch(e){}
    }
  }
  function walkAttrs(root){
    var els=root.querySelectorAll?root.querySelectorAll("[title],[placeholder]"):[];
    for(var i=0;i<els.length;i++){
      var el=els[i], attrs=["title","placeholder"];
      for(var j=0;j<attrs.length;j++){
        var a=attrs[j], v=el.getAttribute(a);
        if(!el.__i18nAttr) el.__i18nAttr={};
        if(el.__i18nAttr[a]===undefined){
          if(!v||!/[\u4e00-\u9fa5]/.test(v)) continue;
          el.__i18nAttr[a]=v;
        }
        var next=translate(el.__i18nAttr[a]);
        if(next!==v) el.setAttribute(a,next);
      }
    }
  }
  function apply(){walkText(document.body);walkAttrs(document.body)}
  function set(lang){
    if(!D.langs.some(function(l){return l.v===lang})) lang="zh-CN";
    cur=lang;
    try{localStorage.setItem("wuai-lang",lang)}catch(e){}
    document.documentElement.lang=lang;
    apply();
    // setPatch -> setRender 会在 set() 之后同步重建设置面板；延时补一次全量扫描兜底
    setTimeout(function(){try{apply()}catch(e){}},80);
    document.dispatchEvent(new CustomEvent("wuai:lang",{detail:{lang:lang}}));
  }
  // 动态节点：增量扫描 + 节流。
  // 关键：绝不 clearTimeout/重置计时器——逐字歌词、进度条、SSE 的高频 mutation
  // 会不断重置 debounce，导致新渲染的节点永远扫不到（必须刷新才生效）。
  var mo=null, timer=0, pending=false, targets=[];
  function scanOneText(n){
    if(!n||n.nodeType!==3) return;
    var p=n.parentNode;
    if(!p||SKIP[p.nodeName]||ignored(p)) return;
    var raw=n.nodeValue;
    if(n.__i18nSrc===undefined){
      if(!raw||!/[一-龥]/.test(raw)) return;
      n.__i18nSrc=raw;
    }
    try{var next=translate(n.__i18nSrc);if(next!==raw) n.nodeValue=next}catch(e){}
  }
  function flushTargets(){
    pending=false;
    var list=targets; targets=[];
    for(var i=0;i<list.length;i++){
      var t=list[i];
      if(t&&t.nodeType===3){scanOneText(t);continue}
      if(!t||!t.parentNode) continue;          // 已从 DOM 移除
      try{walkText(t);walkAttrs(t)}catch(e){}
    }
  }
  function scheduleScan(){
    if(pending) return;                        // 已有排队：保留原计时，防饥饿
    pending=true;
    timer=setTimeout(flushTargets,100);
  }
  function observe(){
    if(mo)return;
    mo=new MutationObserver(function(ms){
      if(cur==="zh-CN")return;
      for(var i=0;i<ms.length;i++){
        var m=ms[i], j;
        if(m.type==="childList"){
          for(j=0;j<m.addedNodes.length;j++){
            var n=m.addedNodes[j];
            if(n.nodeType===1||n.nodeType===3) targets.push(n);
          }
        }else if(m.type==="characterData"){
          targets.push(m.target);
        }
      }
      if(targets.length) scheduleScan();
    });
    mo.observe(document.body,{childList:true,subtree:true,characterData:true});
  }
  window.WAI18N={
    init:function(saved){
      if(ready)return; ready=true;
      cur=saved||"zh-CN";
      try{localStorage.setItem("wuai-lang",cur)}catch(e){}
      document.documentElement.lang=cur;
      function start(){apply();observe()}
      if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",start);
      else start();
    },
    set:set,
    get:function(){return cur},
    t:function(s){return cur==="zh-CN"?s:(translate(s)||s)},
    apply:apply
  };
  // 自动初始化：URL ?lang= 优先（可分享指定语言链接），其次 localStorage，最后中文
  var saved="zh-CN";
  try{
    var qm=String(location.search||"").match(/[?&]lang=([^&]+)/);
    if(qm) saved=decodeURIComponent(qm[1]);
    else saved=localStorage.getItem("wuai-lang")||"zh-CN";
  }catch(e){}
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",function(){window.WAI18N.init(saved)});
  else window.WAI18N.init(saved);
})();
